type Row = Record<string, unknown>;
type ChangeHandler = () => Promise<void>;

const ROLES = ["Quản trị viên", "Người nhập liệu", "Người kiểm tra", "Người chỉ xem"] as const;

export function accessForRole(role: string) {
  const normalized = role === "Quản trị hệ thống" ? "Quản trị viên"
    : role === "Cán bộ Phòng Tổ chức" ? "Người nhập liệu"
      : role === "Trưởng phòng" ? "Người kiểm tra"
        : ["Người xem/báo cáo", "Kiểm toán"].includes(role) ? "Người chỉ xem" : role;
  return {
    role: normalized,
    view: ROLES.includes(normalized as (typeof ROLES)[number]),
    write: ["Quản trị viên", "Người nhập liệu"].includes(normalized),
    approve: ["Quản trị viên", "Người kiểm tra"].includes(normalized),
    restore: normalized === "Quản trị viên",
    admin: normalized === "Quản trị viên",
    export: ROLES.includes(normalized as (typeof ROLES)[number]),
  };
}

function text(row: Row, key: string) {
  const value = row[key];
  const raw = value == null ? "" : String(value).trim();
  if (key !== "organizationScope" || !raw) return raw;
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && typeof parsed[0] === "string") return parsed[0];
  } catch {
    // Legacy rows may store one organization id without JSON wrapping.
  }
  return raw;
}

function displayDate(value: unknown) {
  const raw = value == null ? "" : String(value);
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return match ? `${match[3]}/${match[2]}/${match[1]}` : raw || "—";
}

function downloadBlob(blob: Blob, fileName: string) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1_000);
}

async function mutate(action: string, payload: Row, onDataChanged?: ChangeHandler) {
  const result = await sendOrQueue(action, payload);
  if (result.queued) toast.warning("Mạng gián đoạn: thay đổi đã được giữ trong hàng đợi và sẽ tự gửi lại.");
  else toast.success("Đã lưu và đồng bộ dữ liệu.");
  await onDataChanged?.();
  return result;
}

function Field({ label, required, children }: { label: string; required?: boolean; children: React.ReactNode }) {
  return <label className="grid gap-1.5 text-sm font-medium text-slate-700"><span>{label}{required ? <span className="ml-1 text-rose-600">*</span> : null}</span>{children}</label>;
}

function Empty({ icon: Icon, title, detail }: { icon: React.ComponentType<{ className?: string }>; title: string; detail: string }) {
  return <div className="flex flex-col items-center px-6 py-14 text-center"><span className="rounded-2xl bg-slate-100 p-3 text-slate-400"><Icon className="size-6" /></span><p className="mt-3 font-semibold text-slate-800">{title}</p><p className="mt-1 max-w-lg text-sm leading-6 text-slate-500">{detail}</p></div>;
}

function RecordActions({ canWrite, onEdit, onDelete }: { canWrite: boolean; onEdit: () => void; onDelete: () => void }) {
  if (!canWrite) return <Badge variant="outline">Chỉ xem</Badge>;
  return <div className="flex justify-end gap-1"><Button variant="ghost" size="sm" onClick={onEdit}>Sửa</Button><Button variant="ghost" size="icon" className="text-rose-600" onClick={onDelete} aria-label="Xóa mềm"><Trash2 className="size-4" /></Button></div>;
}

export function V2PeopleView({ search, rows, organizations, role, connected, loading, onDataChanged }: { search: string; rows: Row[]; organizations: Row[]; role: string; connected: boolean; loading: boolean; onDataChanged: ChangeHandler }) {
  const access = accessForRole(role);
  const [unit, setUnit] = React.useState("all");
  const [status, setStatus] = React.useState("all");
  const [page, setPage] = React.useState(1);
  const [selected, setSelected] = React.useState<Set<string>>(new Set());
  const [form, setForm] = React.useState<Row | null>(null);
  const [bulkOpen, setBulkOpen] = React.useState(false);
  const [bulkChanges, setBulkChanges] = React.useState<Row>({ employmentStatus: "Đang công tác", personType: "Viên chức" });
  const [deleteIds, setDeleteIds] = React.useState<string[]>([]);
  const pageSize = 20;
  const query = search.trim().toLocaleLowerCase("vi");
  const filtered = rows.filter((row) => {
    const haystack = [row.staffCode, row.lecturerCode, row.fullName, row.organization, row.workEmail, row.phone].join(" ").toLocaleLowerCase("vi");
    return (!query || haystack.includes(query)) && (unit === "all" || text(row, "organizationId") === unit) && (status === "all" || text(row, "employmentStatus") === status);
  });
  const pages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((Math.min(page, pages) - 1) * pageSize, Math.min(page, pages) * pageSize);
  const statuses = [...new Set(rows.map((row) => text(row, "employmentStatus")).filter(Boolean))];
  const setField = (key: string, value: unknown) => setForm((current) => ({ ...(current ?? {}), [key]: value }));
  const toggle = (id: string, checked: boolean) => setSelected((current) => { const next = new Set(current); if (checked) next.add(id); else next.delete(id); return next; });

  async function save() {
    if (!form) return;
    if (!text(form, "fullName")) return toast.error("Họ và tên là trường bắt buộc.");
    try { await mutate("upsert_person", { record: form, reason: "Cập nhật từ màn hình Hồ sơ nhân sự" }, onDataChanged); setForm(null); }
    catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu hồ sơ."); }
  }

  async function saveBulk() {
    const ids = [...selected];
    if (!ids.length) return toast.error("Chưa chọn hồ sơ.");
    try { await mutate("bulk_update_people", { ids, changes: bulkChanges, reason: `Cập nhật hàng loạt ${ids.length} hồ sơ` }, onDataChanged); setSelected(new Set()); setBulkOpen(false); }
    catch (error) { toast.error(error instanceof Error ? error.message : "Không thể cập nhật hàng loạt."); }
  }

  async function remove() {
    try { await mutate("bulk_delete", { entityType: "person", ids: deleteIds, reason: "Xóa mềm từ danh sách nhân sự" }, onDataChanged); setSelected(new Set()); }
    catch (error) { toast.error(error instanceof Error ? error.message : "Không thể xóa hồ sơ."); }
    finally { setDeleteIds([]); }
  }

  return <div className="space-y-4">
    <div className="flex flex-wrap items-center gap-2 rounded-2xl border bg-white p-3 shadow-sm">
      <Search className="ml-1 size-4 text-slate-400" />
      <Select value={unit} onValueChange={(value) => { setUnit(value); setPage(1); }}><SelectTrigger className="h-10 min-w-[210px] rounded-xl"><SelectValue placeholder="Đơn vị" /></SelectTrigger><SelectContent><SelectItem value="all">Tất cả đơn vị</SelectItem>{organizations.map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "name")}</SelectItem>)}</SelectContent></Select>
      <Select value={status} onValueChange={(value) => { setStatus(value); setPage(1); }}><SelectTrigger className="h-10 min-w-[190px] rounded-xl"><SelectValue placeholder="Trạng thái" /></SelectTrigger><SelectContent><SelectItem value="all">Tất cả trạng thái</SelectItem>{statuses.map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select>
      <Badge variant="outline">{filtered.length.toLocaleString("vi-VN")} hồ sơ</Badge>
      <div className="ml-auto flex flex-wrap gap-2">{selected.size && access.write ? <><Button variant="outline" onClick={() => setBulkOpen(true)}>Sửa {selected.size} dòng</Button><Button variant="outline" className="text-rose-700" onClick={() => setDeleteIds([...selected])}><Trash2 className="size-4" />Xóa mềm</Button></> : null}{access.write ? <Button className="bg-[#0065a8]" onClick={() => setForm({ version: 0, personType: "Viên chức", employmentStatus: "Đang công tác" })}><Plus className="size-4" />Thêm hồ sơ</Button> : null}</div>
    </div>
    <Card className="overflow-hidden rounded-2xl shadow-sm">
      {!connected && !loading ? <div className="border-b border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">Chưa kết nối dữ liệu trung tâm; bảng không dùng dữ liệu cá nhân minh họa thay thế.</div> : null}
      {loading ? <Empty icon={Loader2} title="Đang tải hồ sơ" detail="Hệ thống đang đối soát dữ liệu theo quyền của tài khoản." /> : visible.length ? <div className="overflow-x-auto"><Table><TableHeader className="sticky top-0 z-10 bg-slate-50"><TableRow><TableHead className="w-12"><Checkbox checked={visible.every((row) => selected.has(text(row, "id")))} onCheckedChange={(checked) => visible.forEach((row) => toggle(text(row, "id"), Boolean(checked)))} aria-label="Chọn trang hiện tại" /></TableHead><TableHead className="min-w-[180px]">Mã định danh</TableHead><TableHead className="min-w-[230px]">Họ và tên</TableHead><TableHead>Loại</TableHead><TableHead className="min-w-[190px]">Đơn vị</TableHead><TableHead className="min-w-[170px]">Chức vụ/chức danh</TableHead><TableHead>Trạng thái</TableHead><TableHead>Cập nhật</TableHead><TableHead className="w-28" /></TableRow></TableHeader><TableBody>{visible.map((row) => { const id = text(row, "id"); return <TableRow key={id} data-state={selected.has(id) ? "selected" : undefined}><TableCell><Checkbox checked={selected.has(id)} onCheckedChange={(checked) => toggle(id, Boolean(checked))} aria-label={`Chọn ${text(row, "fullName")}`} /></TableCell><TableCell><p className="font-mono text-xs font-semibold text-slate-700">{text(row, "staffCode") || "Chưa cấp mã CB"}</p><p className="mt-1 font-mono text-xs text-slate-400">{text(row, "lecturerCode") || "Chưa cấp mã GV"}</p></TableCell><TableCell><p className="font-semibold text-slate-900">{text(row, "fullName")}</p><p className="text-xs text-slate-500">{displayDate(row.birthDate)} · {text(row, "gender") || "Chưa xác định"}</p></TableCell><TableCell><Badge variant="outline">{text(row, "personType") || "Viên chức"}</Badge></TableCell><TableCell>{text(row, "organization") || "Chưa xác định"}</TableCell><TableCell><p>{text(row, "position") || "—"}</p><p className="text-xs text-slate-500">{text(row, "professionalTitle")}</p></TableCell><TableCell><Badge className="bg-sky-100 text-sky-800">{text(row, "employmentStatus") || "Chưa cập nhật"}</Badge></TableCell><TableCell><p className="text-xs text-slate-500">v{Number(row.version ?? 1)}</p><p className="text-xs text-slate-400">{displayDate(row.updatedAt)}</p></TableCell><TableCell><RecordActions canWrite={access.write} onEdit={() => setForm({ ...row })} onDelete={() => setDeleteIds([id])} /></TableCell></TableRow>; })}</TableBody></Table></div> : <Empty icon={Users} title="Không có hồ sơ phù hợp" detail="Hãy đổi bộ lọc hoặc nhập dữ liệu từ mẫu chính thức." />}
      <div className="flex items-center justify-between border-t bg-slate-50/70 px-4 py-3 text-sm text-slate-500"><span>Trang {Math.min(page, pages)}/{pages}</span><div className="flex gap-2"><Button variant="outline" size="sm" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Trước</Button><Button variant="outline" size="sm" disabled={page >= pages} onClick={() => setPage((value) => value + 1)}>Sau</Button></div></div>
    </Card>

    <Dialog open={Boolean(form)} onOpenChange={(open) => !open && setForm(null)}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-4xl"><DialogHeader><DialogTitle>{text(form ?? {}, "id") ? "Cập nhật hồ sơ" : "Thêm hồ sơ nhân sự"}</DialogTitle><DialogDescription>Mã cán bộ/mã giảng viên và person_id là khóa ổn định; họ tên không được dùng làm khóa.</DialogDescription></DialogHeader>{form ? <div className="grid gap-4 py-2 md:grid-cols-2 xl:grid-cols-3"><Field label="Họ và tên" required><Input value={text(form, "fullName")} onChange={(event) => setField("fullName", event.target.value)} /></Field><Field label="Mã cán bộ"><Input value={text(form, "staffCode")} onChange={(event) => setField("staffCode", event.target.value)} /></Field><Field label="Mã giảng viên"><Input value={text(form, "lecturerCode")} onChange={(event) => setField("lecturerCode", event.target.value)} /></Field><Field label="Loại nhân sự"><Select value={text(form, "personType") || "Viên chức"} onValueChange={(value) => setField("personType", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Cán bộ", "Giảng viên", "Viên chức", "Người lao động"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Ngày sinh"><Input type="date" value={text(form, "birthDate").slice(0, 10)} onChange={(event) => setField("birthDate", event.target.value)} /></Field><Field label="Giới tính"><Select value={text(form, "gender") || "Chưa xác định"} onValueChange={(value) => setField("gender", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Nam", "Nữ", "Khác", "Chưa xác định"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Đơn vị"><Select value={text(form, "organizationId") || "none"} onValueChange={(value) => { const organization = organizations.find((row) => text(row, "id") === value); setForm((current) => ({ ...(current ?? {}), organizationId: value === "none" ? "" : value, organizationName: organization ? text(organization, "name") : "" })); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Chưa xác định</SelectItem>{organizations.map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "name")}</SelectItem>)}</SelectContent></Select></Field><Field label="Phòng/khoa/bộ môn"><Input value={text(form, "department")} onChange={(event) => setField("department", event.target.value)} /></Field><Field label="Chức vụ"><Input value={text(form, "position")} onChange={(event) => setField("position", event.target.value)} /></Field><Field label="Chức danh nghề nghiệp"><Input value={text(form, "professionalTitle")} onChange={(event) => setField("professionalTitle", event.target.value)} /></Field><Field label="Chuyên môn"><Input value={text(form, "specialization")} onChange={(event) => setField("specialization", event.target.value)} /></Field><Field label="Tình trạng công tác"><Input value={text(form, "employmentStatus")} onChange={(event) => setField("employmentStatus", event.target.value)} /></Field><Field label="Ngày bắt đầu"><Input type="date" value={text(form, "startDate").slice(0, 10)} onChange={(event) => setField("startDate", event.target.value)} /></Field><Field label="Bố trí làm việc"><Input value={text(form, "workArrangement")} onChange={(event) => setField("workArrangement", event.target.value)} /></Field><Field label="Điện thoại"><Input value={text(form, "phone")} onChange={(event) => setField("phone", event.target.value)} /></Field><Field label="Email công vụ"><Input type="email" value={text(form, "workEmail")} onChange={(event) => setField("workEmail", event.target.value)} /></Field><Field label="Email cá nhân"><Input type="email" value={text(form, "personalEmail")} onChange={(event) => setField("personalEmail", event.target.value)} /></Field><Field label="CCCD/định danh"><Input value={text(form, "identityNumber")} onChange={(event) => setField("identityNumber", event.target.value)} /></Field><Field label="Mã số thuế"><Input value={text(form, "taxCode")} onChange={(event) => setField("taxCode", event.target.value)} /></Field><Field label="Mã BHXH"><Input value={text(form, "socialInsuranceNumber")} onChange={(event) => setField("socialInsuranceNumber", event.target.value)} /></Field><Field label="Quê quán"><Input value={text(form, "homeTown")} onChange={(event) => setField("homeTown", event.target.value)} /></Field><Field label="Địa chỉ liên hệ"><Input value={text(form, "address")} onChange={(event) => setField("address", event.target.value)} /></Field><Field label="Ghi chú"><Textarea value={text(form, "notes")} onChange={(event) => setField("notes", event.target.value)} /></Field></div> : null}<DialogFooter><Button variant="outline" onClick={() => setForm(null)}>Hủy</Button><Button className="bg-[#0065a8]" onClick={() => void save()}><Save className="size-4" />Lưu hồ sơ</Button></DialogFooter></DialogContent></Dialog>

    <Dialog open={bulkOpen} onOpenChange={setBulkOpen}><DialogContent><DialogHeader><DialogTitle>Cập nhật {selected.size} hồ sơ</DialogTitle><DialogDescription>Chỉ các trường dưới đây được thay đổi; thao tác được ghi nhật ký.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><Field label="Tình trạng công tác"><Input value={text(bulkChanges, "employmentStatus")} onChange={(event) => setBulkChanges((current) => ({ ...current, employmentStatus: event.target.value }))} /></Field><Field label="Loại nhân sự"><Select value={text(bulkChanges, "personType")} onValueChange={(value) => setBulkChanges((current) => ({ ...current, personType: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Cán bộ", "Giảng viên", "Viên chức", "Người lao động"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Bố trí làm việc"><Input value={text(bulkChanges, "workArrangement")} onChange={(event) => setBulkChanges((current) => ({ ...current, workArrangement: event.target.value }))} /></Field></div><DialogFooter><Button variant="outline" onClick={() => setBulkOpen(false)}>Hủy</Button><Button onClick={() => void saveBulk()} className="bg-[#0065a8]">Xác nhận cập nhật</Button></DialogFooter></DialogContent></Dialog>
    <AlertDialog open={deleteIds.length > 0} onOpenChange={(open) => !open && setDeleteIds([])}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Xóa mềm {deleteIds.length} hồ sơ?</AlertDialogTitle><AlertDialogDescription>Dữ liệu không bị xóa vĩnh viễn. Quản trị viên có thể khôi phục từ Thùng rác và người thao tác có thể hoàn tác trong 30 phút.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Hủy</AlertDialogCancel><AlertDialogAction className="bg-rose-600" onClick={() => void remove()}>Xóa mềm</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </div>;
}

export function V2OrganizationsView({ rows, people, role, onDataChanged }: { rows: Row[]; people: Row[]; role: string; onDataChanged: ChangeHandler }) {
  const access = accessForRole(role);
  const [query, setQuery] = React.useState("");
  const [form, setForm] = React.useState<Row | null>(null);
  const [deleteId, setDeleteId] = React.useState("");
  const filtered = rows.filter((row) => [row.code, row.name, row.shortName, row.level].join(" ").toLocaleLowerCase("vi").includes(query.toLocaleLowerCase("vi")));
  const counts = new Map<string, number>();
  people.forEach((person) => counts.set(text(person, "organizationId"), (counts.get(text(person, "organizationId")) ?? 0) + 1));
  const setField = (key: string, value: unknown) => setForm((current) => ({ ...(current ?? {}), [key]: value }));
  async function save() { if (!form) return; try { await mutate("upsert_organization", { record: form, reason: "Cập nhật danh mục đơn vị" }, onDataChanged); setForm(null); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu đơn vị."); } }
  async function remove() { try { await mutate("bulk_delete", { entityType: "organization", ids: [deleteId], reason: "Xóa mềm đơn vị" }, onDataChanged); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể xóa đơn vị."); } finally { setDeleteId(""); } }
  return <div className="space-y-4"><div className="flex flex-wrap items-center gap-2 rounded-2xl border bg-white p-3 shadow-sm"><Search className="size-4 text-slate-400" /><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Tìm mã hoặc tên đơn vị" className="max-w-md" /><Badge variant="outline">{filtered.length} đơn vị</Badge>{access.write ? <Button className="ml-auto bg-[#0065a8]" onClick={() => setForm({ version: 0, level: "Đơn vị", status: "active" })}><Plus className="size-4" />Thêm đơn vị</Button> : null}</div><Card className="overflow-hidden rounded-2xl shadow-sm">{filtered.length ? <div className="overflow-x-auto"><Table><TableHeader className="bg-slate-50"><TableRow><TableHead>Mã đơn vị</TableHead><TableHead className="min-w-[250px]">Tên chính thức</TableHead><TableHead>Cấp</TableHead><TableHead>Đơn vị cha</TableHead><TableHead className="text-right">Nhân sự</TableHead><TableHead>Trạng thái</TableHead><TableHead className="w-28" /></TableRow></TableHeader><TableBody>{filtered.map((row) => <TableRow key={text(row, "id")}><TableCell className="font-mono text-xs font-semibold">{text(row, "code")}</TableCell><TableCell><p className="font-semibold">{text(row, "name")}</p><p className="text-xs text-slate-500">{text(row, "shortName")}</p></TableCell><TableCell>{text(row, "level")}</TableCell><TableCell>{text(rows.find((candidate) => text(candidate, "id") === text(row, "parentId")) ?? {}, "name") || "—"}</TableCell><TableCell className="text-right font-semibold">{counts.get(text(row, "id")) ?? 0}</TableCell><TableCell><Badge className={text(row, "status") === "active" ? "bg-emerald-100 text-emerald-800" : "bg-slate-100 text-slate-700"}>{text(row, "status") || "active"}</Badge></TableCell><TableCell><RecordActions canWrite={access.write} onEdit={() => setForm({ ...row })} onDelete={() => setDeleteId(text(row, "id"))} /></TableCell></TableRow>)}</TableBody></Table></div> : <Empty icon={Building2} title="Chưa có đơn vị phù hợp" detail="Thêm đơn vị bằng mã chính thức trước khi nhập nhân sự và hợp đồng." />}</Card><Dialog open={Boolean(form)} onOpenChange={(open) => !open && setForm(null)}><DialogContent className="sm:max-w-2xl"><DialogHeader><DialogTitle>{text(form ?? {}, "id") ? "Cập nhật đơn vị" : "Thêm đơn vị"}</DialogTitle><DialogDescription>Mã đơn vị là khóa ổn định dùng chung cho mọi màn hình.</DialogDescription></DialogHeader>{form ? <div className="grid gap-4 py-2 sm:grid-cols-2"><Field label="Mã đơn vị" required><Input value={text(form, "code")} onChange={(event) => setField("code", event.target.value)} /></Field><Field label="Tên viết tắt"><Input value={text(form, "shortName")} onChange={(event) => setField("shortName", event.target.value)} /></Field><div className="sm:col-span-2"><Field label="Tên chính thức" required><Input value={text(form, "name")} onChange={(event) => setField("name", event.target.value)} /></Field></div><Field label="Cấp đơn vị"><Input value={text(form, "level")} onChange={(event) => setField("level", event.target.value)} /></Field><Field label="Đơn vị cha"><Select value={text(form, "parentId") || "none"} onValueChange={(value) => setField("parentId", value === "none" ? "" : value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Không có</SelectItem>{rows.filter((row) => text(row, "id") !== text(form, "id")).map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "name")}</SelectItem>)}</SelectContent></Select></Field><Field label="Trạng thái"><Select value={text(form, "status") || "active"} onValueChange={(value) => setField("status", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="active">Hoạt động</SelectItem><SelectItem value="inactive">Ngừng hoạt động</SelectItem></SelectContent></Select></Field></div> : null}<DialogFooter><Button variant="outline" onClick={() => setForm(null)}>Hủy</Button><Button className="bg-[#0065a8]" onClick={() => void save()}><Save className="size-4" />Lưu đơn vị</Button></DialogFooter></DialogContent></Dialog><AlertDialog open={Boolean(deleteId)} onOpenChange={(open) => !open && setDeleteId("")}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Xóa mềm đơn vị?</AlertDialogTitle><AlertDialogDescription>Hãy chắc chắn đơn vị không còn được dùng cho hồ sơ đang hoạt động. Dữ liệu vẫn có thể khôi phục.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Hủy</AlertDialogCancel><AlertDialogAction className="bg-rose-600" onClick={() => void remove()}>Xóa mềm</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></div>;
}

export function V2ContractsView({ search, rows, people, organizations, role, onDataChanged }: { search: string; rows: Row[]; people: Row[]; organizations: Row[]; role: string; onDataChanged: ChangeHandler }) {
  const access = accessForRole(role);
  const [type, setType] = React.useState("all");
  const [state, setState] = React.useState("all");
  const [due, setDue] = React.useState("all");
  const [form, setForm] = React.useState<Row | null>(null);
  const [deleteId, setDeleteId] = React.useState("");
  const [todayEpoch] = React.useState(() => Date.now());
  const query = search.toLocaleLowerCase("vi");
  const types = [...new Set(rows.map((row) => text(row, "contractType")).filter(Boolean))];
  const states = [...new Set(rows.map((row) => text(row, "status")).filter(Boolean))];
  const filtered = rows.filter((row) => {
    const days = text(row, "endDate") ? Math.ceil((Date.parse(`${text(row, "endDate").slice(0, 10)}T00:00:00Z`) - todayEpoch) / 86_400_000) : null;
    const dueMatch = due === "all" || (days !== null && days >= 0 && days <= Number(due));
    return (!query || [row.contractNumber, row.fullName, row.organization, row.contractType].join(" ").toLocaleLowerCase("vi").includes(query)) && (type === "all" || text(row, "contractType") === type) && (state === "all" || text(row, "status") === state) && dueMatch;
  });
  const setField = (key: string, value: unknown) => setForm((current) => ({ ...(current ?? {}), [key]: value }));
  async function save() { if (!form) return; try { await mutate("upsert_contract", { record: form, reason: "Cập nhật từ màn hình Hợp đồng" }, onDataChanged); setForm(null); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu hợp đồng."); } }
  async function remove() { try { await mutate("bulk_delete", { entityType: "contract", ids: [deleteId], reason: "Xóa mềm hợp đồng" }, onDataChanged); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể xóa hợp đồng."); } finally { setDeleteId(""); } }
  return <div className="space-y-4"><div className="flex flex-wrap items-center gap-2 rounded-2xl border bg-white p-3 shadow-sm"><Select value={type} onValueChange={setType}><SelectTrigger className="h-10 min-w-[210px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Tất cả loại hợp đồng</SelectItem>{types.map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select><Select value={state} onValueChange={setState}><SelectTrigger className="h-10 min-w-[180px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Tất cả trạng thái</SelectItem>{states.map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select><Select value={due} onValueChange={setDue}><SelectTrigger className="h-10 min-w-[170px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Mọi thời hạn</SelectItem>{[7, 15, 30, 60, 90].map((value) => <SelectItem key={value} value={String(value)}>Còn ≤ {value} ngày</SelectItem>)}</SelectContent></Select><Badge variant="outline">{filtered.length} hợp đồng</Badge>{access.write ? <Button className="ml-auto bg-[#0065a8]" onClick={() => setForm({ version: 0, contractType: "Xác định thời hạn", status: "Đang hiệu lực" })}><Plus className="size-4" />Thêm hợp đồng</Button> : null}</div><Card className="overflow-hidden rounded-2xl shadow-sm">{filtered.length ? <div className="overflow-x-auto"><Table><TableHeader className="bg-slate-50"><TableRow><TableHead className="min-w-[170px]">Số hợp đồng</TableHead><TableHead className="min-w-[220px]">Người liên quan</TableHead><TableHead className="min-w-[190px]">Loại hợp đồng</TableHead><TableHead className="min-w-[180px]">Đơn vị sử dụng</TableHead><TableHead>Hiệu lực</TableHead><TableHead>Hết hạn</TableHead><TableHead>Trạng thái</TableHead><TableHead className="w-28" /></TableRow></TableHeader><TableBody>{filtered.slice(0, 500).map((row) => <TableRow key={text(row, "id")}><TableCell><p className="font-mono text-xs font-semibold">{text(row, "contractNumber") || "Chờ bổ sung số"}</p><p className="text-xs text-slate-400">v{Number(row.version ?? 1)} · HS {text(row, "salaryCoefficient") || "—"}</p></TableCell><TableCell><p className="font-semibold">{text(row, "fullName")}</p><p className="font-mono text-xs text-slate-400">{text(row, "personId") || "Chưa liên kết"}</p></TableCell><TableCell>{text(row, "contractType")}</TableCell><TableCell>{text(row, "organization") || "Chưa xác định"}</TableCell><TableCell className="whitespace-nowrap">{displayDate(row.effectiveDate || row.startDate)}</TableCell><TableCell className="whitespace-nowrap">{displayDate(row.endDate)}</TableCell><TableCell><Badge variant="outline">{text(row, "status")}</Badge></TableCell><TableCell><RecordActions canWrite={access.write} onEdit={() => setForm({ ...row })} onDelete={() => setDeleteId(text(row, "id"))} /></TableCell></TableRow>)}</TableBody></Table></div> : <Empty icon={FileClock} title="Không có hợp đồng phù hợp" detail="Đổi bộ lọc hoặc thêm hợp đồng từ dữ liệu đã được xác minh." />}</Card><Dialog open={Boolean(form)} onOpenChange={(open) => !open && setForm(null)}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-4xl"><DialogHeader><DialogTitle>{text(form ?? {}, "id") ? "Cập nhật hợp đồng" : "Thêm hợp đồng"}</DialogTitle><DialogDescription>Hợp đồng liên kết bằng contract_id và person_id; ngày được kiểm tra logic trước khi ghi.</DialogDescription></DialogHeader>{form ? <div className="grid gap-4 py-2 md:grid-cols-2 xl:grid-cols-3"><Field label="Người liên quan"><Select value={text(form, "personId") || "none"} onValueChange={(value) => { const person = people.find((row) => text(row, "id") === value); setForm((current) => ({ ...(current ?? {}), personId: value === "none" ? "" : value, fullName: person ? text(person, "fullName") : text(current ?? {}, "fullName"), birthDate: person ? text(person, "birthDate") : text(current ?? {}, "birthDate"), organizationId: person ? text(person, "organizationId") : text(current ?? {}, "organizationId"), organizationName: person ? text(person, "organization") : text(current ?? {}, "organizationName") })); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Chưa liên kết</SelectItem>{people.slice(0, 1000).map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "staffCode") || "—"} · {text(row, "fullName")}</SelectItem>)}</SelectContent></Select></Field><Field label="Họ tên nguồn" required><Input value={text(form, "fullName")} onChange={(event) => setField("fullName", event.target.value)} /></Field><Field label="Số hợp đồng"><Input value={text(form, "contractNumber")} onChange={(event) => setField("contractNumber", event.target.value)} /></Field><Field label="Loại hợp đồng" required><Select value={text(form, "contractType") || "Xác định thời hạn"} onValueChange={(value) => setField("contractType", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Xác định thời hạn", "Không xác định thời hạn", "Học việc", "Chuyên môn – nghiệp vụ", "Thỉnh giảng", "Giảng viên trình độ cao đã nghỉ hưu", "Loại khác"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Đơn vị sử dụng"><Select value={text(form, "organizationId") || "none"} onValueChange={(value) => { const organization = organizations.find((row) => text(row, "id") === value); setForm((current) => ({ ...(current ?? {}), organizationId: value === "none" ? "" : value, organizationName: organization ? text(organization, "name") : "" })); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Chưa xác định</SelectItem>{organizations.map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "name")}</SelectItem>)}</SelectContent></Select></Field><Field label="Người ký"><Input value={text(form, "signer")} onChange={(event) => setField("signer", event.target.value)} /></Field><Field label="Đơn vị ký"><Input value={text(form, "signingOrganization")} onChange={(event) => setField("signingOrganization", event.target.value)} /></Field><Field label="Chức danh/chuyên môn"><Input value={text(form, "roleOrSpecialty")} onChange={(event) => setField("roleOrSpecialty", event.target.value)} /></Field><Field label="Hệ số lương"><Input value={text(form, "salaryCoefficient")} onChange={(event) => setField("salaryCoefficient", event.target.value)} /></Field><Field label="Ngày ký"><Input type="date" value={text(form, "signedDate").slice(0, 10)} onChange={(event) => setField("signedDate", event.target.value)} /></Field><Field label="Ngày hiệu lực"><Input type="date" value={text(form, "effectiveDate").slice(0, 10)} onChange={(event) => setField("effectiveDate", event.target.value)} /></Field><Field label="Ngày bắt đầu"><Input type="date" value={text(form, "startDate").slice(0, 10)} onChange={(event) => setField("startDate", event.target.value)} /></Field><Field label="Ngày hết hạn"><Input type="date" value={text(form, "endDate").slice(0, 10)} onChange={(event) => setField("endDate", event.target.value)} /></Field><Field label="Số tháng"><Input type="number" min="0" value={text(form, "durationMonths")} onChange={(event) => setField("durationMonths", event.target.value)} /></Field><Field label="Trạng thái"><Input value={text(form, "status")} onChange={(event) => setField("status", event.target.value)} /></Field><Field label="Ngày thanh lý"><Input type="date" value={text(form, "terminatedDate").slice(0, 10)} onChange={(event) => setField("terminatedDate", event.target.value)} /></Field><Field label="Lý do thanh lý"><Input value={text(form, "terminationReason")} onChange={(event) => setField("terminationReason", event.target.value)} /></Field><div className="md:col-span-2 xl:col-span-3"><Field label="Ghi chú"><Textarea value={text(form, "notes")} onChange={(event) => setField("notes", event.target.value)} /></Field></div></div> : null}<DialogFooter><Button variant="outline" onClick={() => setForm(null)}>Hủy</Button><Button className="bg-[#0065a8]" onClick={() => void save()}><Save className="size-4" />Lưu hợp đồng</Button></DialogFooter></DialogContent></Dialog><AlertDialog open={Boolean(deleteId)} onOpenChange={(open) => !open && setDeleteId("")}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Xóa mềm hợp đồng?</AlertDialogTitle><AlertDialogDescription>Hợp đồng vẫn được giữ trong lịch sử và có thể khôi phục; tệp liên quan không bị xóa vật lý.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Hủy</AlertDialogCancel><AlertDialogAction className="bg-rose-600" onClick={() => void remove()}>Xóa mềm</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></div>;
}

export function V2DocumentsView({ rows, people, contracts, role, onDataChanged }: { rows: Row[]; people: Row[]; contracts: Row[]; role: string; onDataChanged: ChangeHandler }) {
  const access = accessForRole(role);
  const [ownerType, setOwnerType] = React.useState("person");
  const [ownerId, setOwnerId] = React.useState("");
  const [replacesId, setReplacesId] = React.useState("none");
  const [file, setFile] = React.useState<File | null>(null);
  const [busy, setBusy] = React.useState(false);
  const ownerRows = ownerType === "person" ? people : contracts;
  const availableReplacements = rows.filter((row) => text(row, "ownerEntityType") === ownerType && text(row, "ownerEntityId") === ownerId);
  async function upload() {
    if (!file || !ownerId) return toast.error("Chọn hồ sơ đích và tệp cần tải.");
    setBusy(true);
    try {
      const form = new FormData(); form.set("file", file); form.set("ownerEntityType", ownerType); form.set("ownerEntityId", ownerId); if (replacesId !== "none") form.set("replacesFileId", replacesId);
      const response = await fetch("/api/files", { method: "POST", body: form });
      const result = await response.json().catch(() => null);
      if (!response.ok) throw new Error(result?.error ?? "Không thể tải tệp.");
      toast.success(`Đã lưu ${file.name} phiên bản ${result.file.fileVersion}.`); setFile(null); setReplacesId("none"); await onDataChanged();
    } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể tải tệp."); }
    finally { setBusy(false); }
  }
  async function remove(id: string) { if (!confirm("Xóa mềm tệp này? Tệp vật lý vẫn được giữ để khôi phục.")) return; try { const response = await fetch(`/api/files?id=${encodeURIComponent(id)}`, { method: "DELETE" }); const result = await response.json().catch(() => null); if (!response.ok) throw new Error(result?.error ?? "Không thể xóa tệp."); toast.success("Đã xóa mềm tệp."); await onDataChanged(); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể xóa tệp."); } }
  return <div className="space-y-4"><Card className="rounded-2xl border-sky-200 bg-gradient-to-br from-white to-sky-50 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Upload className="size-5 text-[#0065a8]" />Gắn tệp vào đúng hồ sơ</CardTitle><CardDescription>Tệp chỉ được lưu khi hồ sơ nhân sự hoặc hợp đồng đích tồn tại và thuộc phạm vi được cấp.</CardDescription></CardHeader><CardContent className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><Field label="Loại hồ sơ"><Select value={ownerType} onValueChange={(value) => { setOwnerType(value); setOwnerId(""); setReplacesId("none"); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="person">Hồ sơ nhân sự</SelectItem><SelectItem value="contract">Hợp đồng</SelectItem></SelectContent></Select></Field><div className="xl:col-span-2"><Field label="Hồ sơ đích"><Select value={ownerId || "none"} onValueChange={setOwnerId}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Chọn hồ sơ</SelectItem>{ownerRows.slice(0, 1000).map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{ownerType === "person" ? `${text(row, "staffCode") || "—"} · ${text(row, "fullName")}` : `${text(row, "contractNumber") || "Chưa số"} · ${text(row, "fullName")}`}</SelectItem>)}</SelectContent></Select></Field></div><Field label="Thay phiên bản"><Select value={replacesId} onValueChange={setReplacesId}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Tệp mới</SelectItem>{availableReplacements.map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>v{Number(row.fileVersion ?? 1)} · {text(row, "fileName")}</SelectItem>)}</SelectContent></Select></Field><div className="flex items-end gap-2"><label className="flex h-10 flex-1 cursor-pointer items-center justify-center rounded-xl border bg-white px-3 text-sm font-semibold"><input type="file" className="sr-only" accept=".pdf,.docx,.xlsx,.xls,.csv,.png,.jpg,.jpeg,.webp" onChange={(event) => setFile(event.target.files?.[0] ?? null)} /><FileText className="mr-2 size-4" />{file ? file.name.slice(0, 18) : "Chọn tệp"}</label><Button disabled={!access.write || busy || !file || !ownerId || ownerId === "none"} className="bg-[#0065a8]" onClick={() => void upload()}>{busy ? <Loader2 className="size-4 animate-spin" /> : <Upload className="size-4" />}Lưu</Button></div></CardContent></Card><Card className="overflow-hidden rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Kho tệp hồ sơ</CardTitle><CardDescription>Mỗi phiên bản có checksum riêng; tải xuống qua đường dẫn được kiểm tra quyền phía máy chủ.</CardDescription></CardHeader>{rows.length ? <div className="overflow-x-auto"><Table><TableHeader className="bg-slate-50"><TableRow><TableHead className="min-w-[230px]">Tên tệp</TableHead><TableHead>Hồ sơ liên kết</TableHead><TableHead>Phiên bản</TableHead><TableHead>Dung lượng</TableHead><TableHead>Người tải</TableHead><TableHead>Ngày tải</TableHead><TableHead className="w-32" /></TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={text(row, "id")}><TableCell><p className="font-semibold">{text(row, "fileName")}</p><p className="font-mono text-[11px] text-slate-400">SHA-256 {text(row, "checksum").slice(0, 12)}…</p></TableCell><TableCell className="font-mono text-xs">{text(row, "ownerEntityType")} · {text(row, "ownerEntityId")}</TableCell><TableCell><Badge variant="outline">v{Number(row.fileVersion ?? 1)}</Badge>{text(row, "replacesFileId") ? <p className="mt-1 text-[11px] text-slate-400">Thay {text(row, "replacesFileId").slice(0, 8)}…</p> : null}</TableCell><TableCell>{(Number(row.sizeBytes ?? 0) / 1024).toLocaleString("vi-VN", { maximumFractionDigits: 1 })} KB</TableCell><TableCell>{text(row, "uploadedBy")}</TableCell><TableCell>{displayDate(row.createdAt)}</TableCell><TableCell><div className="flex justify-end gap-1"><Button asChild variant="outline" size="sm"><a href={`/api/files?id=${encodeURIComponent(text(row, "id"))}&download=1`}><Download className="size-4" />Tải</a></Button>{access.write ? <Button variant="ghost" size="icon" className="text-rose-600" onClick={() => void remove(text(row, "id"))}><Trash2 className="size-4" /></Button> : null}</div></TableCell></TableRow>)}</TableBody></Table></div> : <Empty icon={FileText} title="Chưa có tệp" detail="Chọn hồ sơ đích ở phía trên để tải tệp minh chứng đầu tiên." />}</Card></div>;
}

export function V2ReportsView({ people, contracts, organizations, role }: { people: Row[]; contracts: Row[]; organizations: Row[]; role: string }) {
  const access = accessForRole(role);
  const [dataset, setDataset] = React.useState("people");
  const [unit, setUnit] = React.useState("all");
  const [status, setStatus] = React.useState("all");
  const peopleColumns = [{ key: "staffCode", label: "Mã cán bộ" }, { key: "lecturerCode", label: "Mã giảng viên" }, { key: "fullName", label: "Họ và tên" }, { key: "birthDate", label: "Ngày sinh" }, { key: "gender", label: "Giới tính" }, { key: "organization", label: "Đơn vị" }, { key: "position", label: "Chức vụ" }, { key: "professionalTitle", label: "Chức danh" }, { key: "employmentStatus", label: "Trạng thái" }];
  const contractColumns = [{ key: "contractNumber", label: "Số hợp đồng" }, { key: "fullName", label: "Họ và tên" }, { key: "contractType", label: "Loại hợp đồng" }, { key: "organization", label: "Đơn vị" }, { key: "signedDate", label: "Ngày ký" }, { key: "effectiveDate", label: "Ngày hiệu lực" }, { key: "endDate", label: "Ngày hết hạn" }, { key: "salaryCoefficient", label: "Hệ số lương" }, { key: "status", label: "Trạng thái" }];
  const columns = dataset === "people" ? peopleColumns : contractColumns;
  const [selectedColumns, setSelectedColumns] = React.useState<string[]>(() => [...new Set([...peopleColumns, ...contractColumns].map((column) => column.key))]);
  const source = dataset === "people" ? people : contracts;
  const rows = source.filter((row) => (unit === "all" || text(row, "organizationId") === unit) && (status === "all" || text(row, dataset === "people" ? "employmentStatus" : "status") === status));
  const visibleColumns = columns.filter((column) => selectedColumns.includes(column.key));
  const exported = rows.map((row) => Object.fromEntries(visibleColumns.map((column) => [column.label, column.key.toLowerCase().includes("date") ? displayDate(row[column.key]) : text(row, column.key)])));
  const title = dataset === "people" ? "Danh sách cán bộ, giảng viên, viên chức và người lao động" : "Danh sách hợp đồng";
  const fileBase = `UED_${dataset === "people" ? "nhan_su" : "hop_dong"}_${new Date().toISOString().slice(0, 10)}`;
  function log(format: string) { void sendOrQueue("log_export", { reportType: dataset, format, rowCount: rows.length, filters: { organizationId: unit, status } }).catch(() => undefined); }
  function csv() { if (!exported.length) return toast.error("Không có dữ liệu để xuất."); const headers = Object.keys(exported[0]); const lines = [headers, ...exported.map((row) => Object.values(row))].map((line) => line.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\r\n"); downloadBlob(new Blob(["\ufeff" + lines], { type: "text/csv;charset=utf-8" }), `${fileBase}.csv`); log("csv"); }
  function xlsx() { const runtime = (window as unknown as { XLSX?: { utils: { json_to_sheet: (rows: unknown[]) => unknown; book_new: () => unknown; book_append_sheet: (workbook: unknown, sheet: unknown, name: string) => void }; writeFile: (workbook: unknown, name: string) => void } }).XLSX; if (!runtime || !exported.length) return toast.error("Bộ xuất Excel chưa sẵn sàng hoặc không có dữ liệu."); const workbook = runtime.utils.book_new(); runtime.utils.book_append_sheet(workbook, runtime.utils.json_to_sheet(exported), "BaoCao"); runtime.writeFile(workbook, `${fileBase}.xlsx`); log("xlsx"); }
  async function docx() { const runtime = (window as unknown as { docx?: Record<string, any> }).docx; if (!runtime || !exported.length) return toast.error("Bộ xuất Word chưa sẵn sàng hoặc không có dữ liệu."); const logo = await fetch("/ued-logo.png").then((response) => response.arrayBuffer()); const tableRows = [new runtime.TableRow({ tableHeader: true, children: visibleColumns.map((column) => new runtime.TableCell({ shading: { fill: "DCEEF8" }, children: [new runtime.Paragraph({ children: [new runtime.TextRun({ text: column.label, bold: true, size: 18 })] })] })) }), ...exported.map((row) => new runtime.TableRow({ children: Object.values(row).map((value) => new runtime.TableCell({ children: [new runtime.Paragraph({ children: [new runtime.TextRun({ text: String(value), size: 17 })] })] })) }))]; const document = new runtime.Document({ sections: [{ children: [new runtime.Paragraph({ alignment: runtime.AlignmentType.CENTER, children: [new runtime.ImageRun({ data: logo, transformation: { width: 54, height: 54 } })] }), new runtime.Paragraph({ alignment: runtime.AlignmentType.CENTER, children: [new runtime.TextRun({ text: "TRƯỜNG ĐẠI HỌC SƯ PHẠM – ĐẠI HỌC ĐÀ NẴNG", bold: true, size: 24 })] }), new runtime.Paragraph({ alignment: runtime.AlignmentType.CENTER, children: [new runtime.TextRun({ text: title.toUpperCase(), bold: true, size: 28, color: "0065A8" })] }), new runtime.Table({ width: { size: 100, type: runtime.WidthType.PERCENTAGE }, rows: tableRows }), new runtime.Paragraph({ children: [new runtime.TextRun({ text: `Tổng số ${rows.length} dòng · Xuất lúc ${new Date().toLocaleString("vi-VN")}`, italics: true, size: 17 })] })] }] }); downloadBlob(await runtime.Packer.toBlob(document), `${fileBase}.docx`); log("docx"); }
  async function pdf() { const runtime = (window as unknown as { pdfMake?: { createPdf: (definition: unknown) => { download: (name: string) => void } } }).pdfMake; if (!runtime || !exported.length) return toast.error("Bộ xuất PDF chưa sẵn sàng hoặc không có dữ liệu."); const logo = await fetch("/ued-logo.png").then((response) => response.blob()).then((blob) => new Promise<string>((resolve) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.readAsDataURL(blob); })); const body = [visibleColumns.map((column) => ({ text: column.label, bold: true, color: "#fff", fillColor: "#0065a8" })), ...exported.map((row) => Object.values(row).map(String))]; runtime.createPdf({ pageSize: "A4", pageOrientation: "landscape", pageMargins: [24, 46, 24, 34], header: { columns: [{ image: logo, width: 26, margin: [24, 7, 0, 0] }, { text: "TRƯỜNG ĐẠI HỌC SƯ PHẠM – ĐẠI HỌC ĐÀ NẴNG", bold: true, fontSize: 9, margin: [4, 14, 0, 0] }] }, footer: (current: number, total: number) => ({ text: `Trang ${current}/${total}`, alignment: "right", margin: [0, 8, 24, 0], fontSize: 8 }), content: [{ text: title.toUpperCase(), alignment: "center", color: "#0065a8", bold: true, fontSize: 14, margin: [0, 0, 0, 4] }, { text: `Bộ lọc: ${unit === "all" ? "Toàn phạm vi" : text(organizations.find((row) => text(row, "id") === unit) ?? {}, "name")} · ${status === "all" ? "Mọi trạng thái" : status} · ${rows.length} dòng`, alignment: "center", fontSize: 8, color: "#64748b", margin: [0, 0, 0, 12] }, { table: { headerRows: 1, widths: visibleColumns.map(() => "auto"), body }, layout: "lightHorizontalLines" }], defaultStyle: { font: "Roboto", fontSize: 7 } }).download(`${fileBase}.pdf`); log("pdf"); }
  return <div className="grid gap-4 xl:grid-cols-[340px_1fr]"><Card className="h-fit rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Trình tạo báo cáo</CardTitle><CardDescription>Bộ lọc và cột xuất dùng trực tiếp trên dữ liệu đã được cấp quyền.</CardDescription></CardHeader><CardContent className="space-y-4"><Field label="Nguồn dữ liệu"><Select value={dataset} onValueChange={setDataset}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="people">Hồ sơ nhân sự</SelectItem><SelectItem value="contracts">Hợp đồng</SelectItem></SelectContent></Select></Field><Field label="Đơn vị"><Select value={unit} onValueChange={setUnit}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Toàn phạm vi</SelectItem>{organizations.map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "name")}</SelectItem>)}</SelectContent></Select></Field><Field label="Trạng thái"><Input value={status === "all" ? "" : status} placeholder="Để trống: tất cả" onChange={(event) => setStatus(event.target.value || "all")} /></Field><div><p className="mb-2 text-sm font-medium text-slate-700">Cột báo cáo</p><div className="grid gap-2 rounded-xl border p-3">{columns.map((column) => <label key={column.key} className="flex items-center gap-2 text-sm"><Checkbox checked={selectedColumns.includes(column.key)} onCheckedChange={(checked) => setSelectedColumns((current) => Boolean(checked) ? [...new Set([...current, column.key])] : current.filter((key) => key !== column.key))} />{column.label}</label>)}</div></div><Badge variant="outline">{rows.length.toLocaleString("vi-VN")} dòng kết quả</Badge></CardContent></Card><div className="space-y-4"><div className="flex flex-wrap gap-2 rounded-2xl border bg-white p-3 shadow-sm"><Button variant="outline" disabled={!access.export} onClick={xlsx}><FileSpreadsheet className="size-4" />XLSX</Button><Button variant="outline" disabled={!access.export} onClick={csv}><FileText className="size-4" />CSV</Button><Button variant="outline" disabled={!access.export} onClick={() => void docx()}><FileText className="size-4" />DOCX</Button><Button variant="outline" disabled={!access.export} onClick={() => void pdf()}><FileText className="size-4" />PDF</Button><Button variant="outline" onClick={() => window.print()}><Download className="size-4" />Bản in</Button></div><Card className="overflow-hidden rounded-2xl shadow-sm"><CardHeader className="border-b"><div className="flex items-center gap-3"><Image src="/ued-logo.png" alt="Logo UED" width={56} height={56} className="size-14 object-contain" /><div><p className="text-xs font-bold uppercase text-slate-600">Trường Đại học Sư phạm – Đại học Đà Nẵng</p><CardTitle className="mt-1 text-lg text-[#0065a8]">{title}</CardTitle><CardDescription>{rows.length} dòng · Lập lúc {new Date().toLocaleString("vi-VN")}</CardDescription></div></div></CardHeader>{exported.length ? <div className="overflow-x-auto"><Table><TableHeader className="bg-[#0065a8]"><TableRow>{visibleColumns.map((column) => <TableHead key={column.key} className="whitespace-nowrap text-white">{column.label}</TableHead>)}</TableRow></TableHeader><TableBody>{exported.slice(0, 100).map((row, index) => <TableRow key={index}>{Object.values(row).map((value, cellIndex) => <TableCell key={cellIndex} className="whitespace-nowrap text-xs">{String(value) || "—"}</TableCell>)}</TableRow>)}</TableBody></Table></div> : <Empty icon={FileSpreadsheet} title="Không có dữ liệu báo cáo" detail="Thay đổi bộ lọc hoặc chọn ít nhất một cột." />}</Card></div></div>;
}

export function V2AdminView({ accounts, organizations, positions, academicYears, settings, trash, role, onDataChanged }: { accounts: Row[]; organizations: Row[]; positions: Row[]; academicYears: Row[]; settings: Row[]; trash: Row[]; role: string; onDataChanged: ChangeHandler }) {
  const access = accessForRole(role);
  const [account, setAccount] = React.useState<Row | null>(null);
  const [position, setPosition] = React.useState<Row | null>(null);
  const [year, setYear] = React.useState<Row | null>(null);
  const currentSettings = (settings.find((row) => text(row, "key") === "app")?.value ?? {}) as Row;
  const [settingsForm, setSettingsForm] = React.useState<Row>({ alertThresholds: Array.isArray(currentSettings.alertThresholds) ? currentSettings.alertThresholds.join(", ") : "7, 15, 30, 60, 90", undoMinutes: Number(currentSettings.undoMinutes ?? 30), automaticBackupDays: Number(currentSettings.automaticBackupDays ?? 7), reminderFrequency: text(currentSettings, "reminderFrequency") || "daily" });
  if (!access.admin) return <Card className="rounded-2xl shadow-sm"><Empty icon={ShieldCheck} title="Khu vực dành cho Quản trị viên" detail="Tài khoản hiện tại không có quyền xem danh sách tài khoản, thay danh mục hoặc khôi phục dữ liệu." /></Card>;
  async function saveAccount() { if (!account) return; try { await mutate("upsert_account", { record: account, reason: "Cập nhật tài khoản và phân quyền" }, onDataChanged); setAccount(null); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu tài khoản."); } }
  async function savePosition() { if (!position) return; try { await mutate("upsert_position", { record: position, reason: "Cập nhật danh mục chức vụ" }, onDataChanged); setPosition(null); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu danh mục."); } }
  async function saveYear() { if (!year) return; try { await mutate("upsert_academic_year", { record: year, reason: "Cập nhật năm học" }, onDataChanged); setYear(null); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu năm học."); } }
  async function saveSystemSettings() { const thresholds = text(settingsForm, "alertThresholds").split(/[,;\s]+/).map(Number).filter(Boolean); try { await mutate("save_settings", { settings: { ...settingsForm, alertThresholds: thresholds }, reason: "Cập nhật cấu hình hệ thống" }, onDataChanged); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu cấu hình."); } }
  async function restore(row: Row) { try { await mutate("bulk_restore", { entityType: text(row, "entityType"), ids: [text(row, "id")], reason: "Khôi phục từ Thùng rác" }, onDataChanged); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể khôi phục."); } }
  return <div className="space-y-4"><Tabs defaultValue="accounts" className="space-y-4"><TabsList className="h-auto flex-wrap rounded-xl bg-slate-200/70 p-1"><TabsTrigger value="accounts">Tài khoản</TabsTrigger><TabsTrigger value="catalogs">Danh mục – Năm học</TabsTrigger><TabsTrigger value="settings">Cảnh báo – Sao lưu</TabsTrigger><TabsTrigger value="trash">Thùng rác</TabsTrigger><TabsTrigger value="branding">Nhận diện</TabsTrigger></TabsList><TabsContent value="accounts"><Card className="overflow-hidden rounded-2xl shadow-sm"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle className="text-base">Tài khoản Google được cấp quyền</CardTitle><CardDescription>Tối đa 5 tài khoản đang hoạt động; không lưu mật khẩu hoặc access token.</CardDescription></div><Button disabled={accounts.filter((row) => Boolean(row.isActive)).length >= 5} className="bg-[#0065a8]" onClick={() => setAccount({ role: "Người chỉ xem", isActive: true, organizationScope: "" })}><Plus className="size-4" />Thêm tài khoản</Button></CardHeader><div className="overflow-x-auto"><Table><TableHeader className="bg-slate-50"><TableRow><TableHead>Email</TableHead><TableHead>Vai trò</TableHead><TableHead>Phạm vi</TableHead><TableHead>Trạng thái</TableHead><TableHead className="w-24" /></TableRow></TableHeader><TableBody>{accounts.map((row) => <TableRow key={text(row, "id")}><TableCell className="font-semibold">{text(row, "email")}</TableCell><TableCell><Badge variant="outline">{text(row, "role")}</Badge></TableCell><TableCell className="text-sm text-slate-500">{text(row, "organizationScope") || "Toàn trường"}</TableCell><TableCell><Badge className={row.isActive ? "bg-emerald-100 text-emerald-800" : "bg-slate-100 text-slate-700"}>{row.isActive ? "Hoạt động" : "Đã khóa"}</Badge></TableCell><TableCell><Button variant="ghost" size="sm" onClick={() => setAccount({ ...row })}>Sửa</Button></TableCell></TableRow>)}</TableBody></Table></div><CardContent className="border-t bg-slate-50/60 py-3 text-xs text-slate-500">{accounts.filter((row) => Boolean(row.isActive)).length}/5 tài khoản đang hoạt động.</CardContent></Card></TabsContent><TabsContent value="catalogs"><div className="grid gap-4 xl:grid-cols-2"><Card className="rounded-2xl shadow-sm"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle className="text-base">Chức vụ và chức danh</CardTitle><CardDescription>Dùng mã danh mục thống nhất trên toàn hệ thống.</CardDescription></div><Button variant="outline" onClick={() => setPosition({ positionType: "Chức vụ", status: "active" })}><Plus className="size-4" />Thêm</Button></CardHeader><CardContent className="space-y-2">{positions.length ? positions.map((row) => <button key={text(row, "id")} onClick={() => setPosition({ ...row })} className="flex w-full items-center gap-3 rounded-xl border p-3 text-left hover:border-sky-200"><span className="rounded-xl bg-sky-100 p-2 text-sky-700"><UserCog className="size-4" /></span><span className="flex-1"><span className="block font-semibold">{text(row, "name")}</span><span className="text-xs text-slate-500">{text(row, "code")} · {text(row, "positionType")}</span></span></button>) : <Empty icon={UserCog} title="Chưa có danh mục chức vụ" detail="Thêm mã chức vụ/chức danh đầu tiên." />}</CardContent></Card><Card className="rounded-2xl shadow-sm"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle className="text-base">Năm học</CardTitle><CardDescription>Năm hiện hành dùng cho lọc, cảnh báo và báo cáo.</CardDescription></div><Button variant="outline" onClick={() => setYear({ isCurrent: academicYears.length === 0 })}><Plus className="size-4" />Thêm</Button></CardHeader><CardContent className="space-y-2">{academicYears.length ? academicYears.map((row) => <button key={text(row, "id")} onClick={() => setYear({ ...row })} className="flex w-full items-center justify-between rounded-xl border p-3 text-left hover:border-sky-200"><span><span className="block font-semibold">{text(row, "name")}</span><span className="text-xs text-slate-500">{displayDate(row.startDate)} – {displayDate(row.endDate)}</span></span>{row.isCurrent ? <Badge className="bg-emerald-100 text-emerald-800">Hiện hành</Badge> : null}</button>) : <Empty icon={History} title="Chưa có năm học" detail="Thêm năm học để dùng thống nhất trên các báo cáo." />}</CardContent></Card></div></TabsContent><TabsContent value="settings"><Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Cấu hình cảnh báo và an toàn dữ liệu</CardTitle><CardDescription>Mốc cảnh báo được quét lại bằng khóa chống trùng; thay đổi được ghi nhật ký.</CardDescription></CardHeader><CardContent className="grid gap-4 md:grid-cols-2"><Field label="Mốc cảnh báo (ngày)"><Input value={text(settingsForm, "alertThresholds")} onChange={(event) => setSettingsForm((current) => ({ ...current, alertThresholds: event.target.value }))} /></Field><Field label="Thời gian hoàn tác (phút)"><Input type="number" min="1" max="1440" value={text(settingsForm, "undoMinutes")} onChange={(event) => setSettingsForm((current) => ({ ...current, undoMinutes: Number(event.target.value) }))} /></Field><Field label="Chu kỳ sao lưu tự động (ngày)"><Input type="number" min="1" max="365" value={text(settingsForm, "automaticBackupDays")} onChange={(event) => setSettingsForm((current) => ({ ...current, automaticBackupDays: Number(event.target.value) }))} /></Field><Field label="Tần suất nhắc"><Select value={text(settingsForm, "reminderFrequency")} onValueChange={(value) => setSettingsForm((current) => ({ ...current, reminderFrequency: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="daily">Mỗi ngày</SelectItem><SelectItem value="weekly">Mỗi tuần</SelectItem></SelectContent></Select></Field><div className="md:col-span-2"><Button className="bg-[#0065a8]" onClick={() => void saveSystemSettings()}><Save className="size-4" />Lưu cấu hình</Button></div></CardContent></Card></TabsContent><TabsContent value="trash"><Card className="overflow-hidden rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Bản ghi đã xóa mềm</CardTitle><CardDescription>Khôi phục không đổi mã định danh và không làm mất lịch sử.</CardDescription></CardHeader>{trash.length ? <div className="overflow-x-auto"><Table><TableHeader className="bg-slate-50"><TableRow><TableHead>Loại</TableHead><TableHead>Nội dung</TableHead><TableHead>Mã</TableHead><TableHead>Thời gian xóa</TableHead><TableHead /></TableRow></TableHeader><TableBody>{trash.map((row) => <TableRow key={`${text(row, "entityType")}-${text(row, "id")}`}><TableCell><Badge variant="outline">{text(row, "entityType")}</Badge></TableCell><TableCell className="font-semibold">{text(row, "label")}</TableCell><TableCell className="font-mono text-xs">{text(row, "id")}</TableCell><TableCell>{displayDate(row.deletedAt)}</TableCell><TableCell className="text-right"><Button variant="outline" size="sm" onClick={() => void restore(row)}><ArchiveRestore className="size-4" />Khôi phục</Button></TableCell></TableRow>)}</TableBody></Table></div> : <Empty icon={Trash2} title="Thùng rác đang trống" detail="Các thao tác xóa mềm sẽ xuất hiện tại đây." />}</Card></TabsContent><TabsContent value="branding"><Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Logo chính thức UED</CardTitle><CardDescription>Giữ nguyên tỉ lệ, nền trong suốt và dùng đồng nhất trên giao diện, mẫu Excel, Word và PDF.</CardDescription></CardHeader><CardContent className="flex flex-col gap-5 sm:flex-row sm:items-center"><div className="flex size-32 items-center justify-center rounded-3xl border bg-white p-4"><Image src="/ued-logo.png" alt="Logo chính thức UED" width={128} height={128} className="size-full object-contain" /></div><div><p className="font-semibold">Trường Đại học Sư phạm – Đại học Đà Nẵng</p><p className="mt-1 font-mono text-xs text-slate-500">SHA-256: f5c6059fcbd09af008a174e27f05fb3bfffcd1200fea2335395152e8e8981a87</p><Badge className="mt-3 bg-emerald-100 text-emerald-800"><CheckCircle2 className="size-3" />Đã khóa nhận diện</Badge></div></CardContent></Card></TabsContent></Tabs><Dialog open={Boolean(account)} onOpenChange={(open) => !open && setAccount(null)}><DialogContent><DialogHeader><DialogTitle>Cấp quyền tài khoản</DialogTitle><DialogDescription>Chỉ nhập email; hệ thống không yêu cầu mật khẩu Gmail.</DialogDescription></DialogHeader>{account ? <div className="grid gap-4 py-2"><Field label="Email Google" required><Input type="email" value={text(account, "email")} onChange={(event) => setAccount((current) => ({ ...(current ?? {}), email: event.target.value }))} /></Field><Field label="Vai trò"><Select value={text(account, "role") || "Người chỉ xem"} onValueChange={(value) => setAccount((current) => ({ ...(current ?? {}), role: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{ROLES.map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Phạm vi đơn vị"><Select value={text(account, "organizationScope") || "all"} onValueChange={(value) => setAccount((current) => ({ ...(current ?? {}), organizationScope: value === "all" ? "" : JSON.stringify([value]) }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Toàn trường</SelectItem>{organizations.map((row) => <SelectItem key={text(row, "id")} value={text(row, "id")}>{text(row, "name")}</SelectItem>)}</SelectContent></Select></Field><label className="flex items-center gap-2 text-sm"><Checkbox checked={account.isActive !== false && account.isActive !== 0} onCheckedChange={(checked) => setAccount((current) => ({ ...(current ?? {}), isActive: Boolean(checked) }))} />Tài khoản đang hoạt động</label></div> : null}<DialogFooter><Button variant="outline" onClick={() => setAccount(null)}>Hủy</Button><Button className="bg-[#0065a8]" onClick={() => void saveAccount()}>Lưu quyền</Button></DialogFooter></DialogContent></Dialog><Dialog open={Boolean(position)} onOpenChange={(open) => !open && setPosition(null)}><DialogContent><DialogHeader><DialogTitle>Chức vụ/chức danh</DialogTitle><DialogDescription>Mã danh mục không đổi sau khi đã liên kết dữ liệu.</DialogDescription></DialogHeader>{position ? <div className="grid gap-4 py-2"><Field label="Mã" required><Input value={text(position, "code")} onChange={(event) => setPosition((current) => ({ ...(current ?? {}), code: event.target.value }))} /></Field><Field label="Tên" required><Input value={text(position, "name")} onChange={(event) => setPosition((current) => ({ ...(current ?? {}), name: event.target.value }))} /></Field><Field label="Loại"><Select value={text(position, "positionType") || "Chức vụ"} onValueChange={(value) => setPosition((current) => ({ ...(current ?? {}), positionType: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="Chức vụ">Chức vụ</SelectItem><SelectItem value="Chức danh nghề nghiệp">Chức danh nghề nghiệp</SelectItem><SelectItem value="Học hàm">Học hàm</SelectItem></SelectContent></Select></Field></div> : null}<DialogFooter><Button variant="outline" onClick={() => setPosition(null)}>Hủy</Button><Button className="bg-[#0065a8]" onClick={() => void savePosition()}>Lưu danh mục</Button></DialogFooter></DialogContent></Dialog><Dialog open={Boolean(year)} onOpenChange={(open) => !open && setYear(null)}><DialogContent><DialogHeader><DialogTitle>Năm học</DialogTitle><DialogDescription>Ngày bắt đầu phải trước ngày kết thúc.</DialogDescription></DialogHeader>{year ? <div className="grid gap-4 py-2"><Field label="Mã năm học" required><Input value={text(year, "code")} onChange={(event) => setYear((current) => ({ ...(current ?? {}), code: event.target.value, name: event.target.value }))} /></Field><Field label="Tên hiển thị"><Input value={text(year, "name")} onChange={(event) => setYear((current) => ({ ...(current ?? {}), name: event.target.value }))} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Bắt đầu"><Input type="date" value={text(year, "startDate").slice(0, 10)} onChange={(event) => setYear((current) => ({ ...(current ?? {}), startDate: event.target.value }))} /></Field><Field label="Kết thúc"><Input type="date" value={text(year, "endDate").slice(0, 10)} onChange={(event) => setYear((current) => ({ ...(current ?? {}), endDate: event.target.value }))} /></Field></div><label className="flex items-center gap-2 text-sm"><Checkbox checked={Boolean(year.isCurrent)} onCheckedChange={(checked) => setYear((current) => ({ ...(current ?? {}), isCurrent: Boolean(checked) }))} />Đặt làm năm học hiện hành</label></div> : null}<DialogFooter><Button variant="outline" onClick={() => setYear(null)}>Hủy</Button><Button className="bg-[#0065a8]" onClick={() => void saveYear()}>Lưu năm học</Button></DialogFooter></DialogContent></Dialog></div>;
}

export function V2SyncView({ online, syncing, outboxCount, lastSync, syncNow, dashboard, role, onDataChanged }: { online: boolean; syncing: boolean; outboxCount: number; lastSync: string; syncNow: () => Promise<void>; dashboard: Row | null; role: string; onDataChanged: ChangeHandler }) {
  const access = accessForRole(role);
  const [checking, setChecking] = React.useState(false);
  const [restoring, setRestoring] = React.useState(false);
  const [outbox, setOutbox] = React.useState<Row[]>([]);
  React.useEffect(() => { void getOutbox().then((items) => setOutbox(items as unknown as Row[])).catch(() => setOutbox([])); }, [outboxCount]);
  async function reconcile() { setChecking(true); try { const result = await sendOrQueue("reconcile", {}); const data = result.data as Row; if (data.passed) toast.success("Đối soát đạt: số lượng, khóa liên kết và checksum nhất quán."); else toast.warning("Đối soát phát hiện vấn đề; dữ liệu không bị xóa."); await onDataChanged(); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể đối soát."); } finally { setChecking(false); } }
  async function retry() { try { const result = await retryFailedMutations(); toast.success(`Đã đưa ${result.reset} thay đổi lỗi về hàng đợi thử lại.`); await syncNow(); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể thử lại."); } }
  async function backup() { try { const response = await fetch("/api/workspace?resource=backup"); const blob = await response.blob(); if (!response.ok) throw new Error("Không thể tạo sao lưu."); downloadBlob(blob, `UED_sao_luu_v3_${new Date().toISOString().slice(0, 10)}.json`); toast.success("Đã tạo sao lưu v3 kèm checksum."); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể tạo sao lưu."); } }
  async function restoreFile(file: File | undefined) { if (!file) return; setRestoring(true); try { const backupObject = JSON.parse(await file.text()); const result = await sendOrQueue("restore_backup", { backup: backupObject, reason: `Khôi phục từ ${file.name}` }); if (result.queued) throw new Error("Khôi phục cần kết nối trực tuyến; thao tác chưa được ghi."); toast.success("Đã kiểm tra checksum và khôi phục dữ liệu hợp lệ."); await onDataChanged(); } catch (error) { toast.error(error instanceof Error ? error.message : "Tệp sao lưu không hợp lệ."); } finally { setRestoring(false); } }
  const counts = (dashboard?.counts ?? {}) as Row;
  const passed = Boolean(dashboard?.passed);
  return <div className="space-y-4"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SyncTile icon={online ? Wifi : WifiOff} label="Kết nối" value={online ? "Trực tuyến" : "Ngoại tuyến"} tone={online ? "green" : "amber"} /><SyncTile icon={Cloud} label="Hàng đợi" value={String(outboxCount)} tone={outboxCount ? "amber" : "green"} /><SyncTile icon={AlertTriangle} label="Xung đột mở" value={String(Number(counts.openConflicts ?? 0))} tone={Number(counts.openConflicts ?? 0) ? "amber" : "green"} /><SyncTile icon={History} label="Đồng bộ gần nhất" value={lastSync} tone="blue" /></div><Card className="rounded-2xl shadow-sm"><CardHeader className="flex flex-row items-start justify-between gap-3"><div><CardTitle className="text-base">Đối soát và tự phục hồi</CardTitle><CardDescription>Dữ liệu hợp lệ tiếp tục được gửi; bản ghi lỗi ở riêng trong hàng đợi để sửa và thử lại.</CardDescription></div><Badge className={passed ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}>{passed ? "Toàn vẹn đạt" : "Cần kiểm tra"}</Badge></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 md:grid-cols-4">{[{ label: "1. Outbox", detail: "Idempotency key" }, { label: "2. Phiên bản", detail: "Kiểm tra trước ghi" }, { label: "3. Xung đột", detail: "Không ghi đè" }, { label: "4. Checksum", detail: "Đối soát cuối" }].map((item, index) => <div key={item.label} className="rounded-xl border bg-slate-50 p-4"><span className={cn("flex size-8 items-center justify-center rounded-full text-sm font-bold", passed ? "bg-emerald-500 text-white" : index === 0 ? "bg-sky-600 text-white" : "bg-slate-200 text-slate-500")}>{passed ? <Check className="size-4" /> : index + 1}</span><p className="mt-3 font-semibold">{item.label}</p><p className="text-xs text-slate-500">{item.detail}</p></div>)}</div><Progress value={passed ? 100 : outboxCount ? 25 : 75} /><div className="flex flex-wrap gap-2"><Button disabled={syncing || !online} onClick={() => void syncNow()} className="bg-[#0065a8]">{syncing ? <Loader2 className="size-4 animate-spin" /> : <Cloud className="size-4" />}Gửi hàng đợi</Button><Button variant="outline" disabled={checking || !online} onClick={() => void reconcile()}>{checking ? <Loader2 className="size-4 animate-spin" /> : <RefreshCw className="size-4" />}Tự kiểm tra</Button><Button variant="outline" disabled={!outbox.some((row) => row.blocked || row.lastError)} onClick={() => void retry()}><RotateCcw className="size-4" />Thử lại bản ghi lỗi</Button><Button variant="outline" disabled={!access.restore} onClick={() => void backup()}><Download className="size-4" />Tạo sao lưu</Button>{access.restore ? <label className="inline-flex h-10 cursor-pointer items-center gap-2 rounded-xl border bg-white px-4 text-sm font-semibold"><input type="file" accept="application/json,.json" className="sr-only" disabled={restoring} onChange={(event) => void restoreFile(event.target.files?.[0])} />{restoring ? <Loader2 className="size-4 animate-spin" /> : <ArchiveRestore className="size-4" />}Khôi phục có kiểm tra</label> : null}</div></CardContent></Card><div className="grid gap-4 lg:grid-cols-2"><Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Hàng đợi cục bộ</CardTitle><CardDescription>Đóng trình duyệt hoặc mất mạng không làm mất thay đổi đang chờ.</CardDescription></CardHeader><CardContent className="space-y-2">{outbox.length ? outbox.slice(0, 20).map((row) => <div key={text(row, "id")} className="rounded-xl border p-3"><div className="flex items-center gap-2"><Badge variant="outline">{text(row, "action")}</Badge><span className="ml-auto text-xs text-slate-500">Lần thử {Number(row.attempts ?? 0)}</span></div><p className="mt-2 text-xs text-slate-500">{text(row, "lastError") || "Đang chờ gửi"}</p></div>) : <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800"><CheckCircle2 className="mr-2 inline size-4" />Không có thay đổi đang chờ.</div>}</CardContent></Card><Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle className="text-base">Nguồn sự thật dùng chung</CardTitle><CardDescription>Dữ liệu trung tâm không phụ thuộc một trình duyệt hoặc Drive cá nhân.</CardDescription></CardHeader><CardContent className="space-y-3"><Connection label="Dữ liệu cấu trúc" value="CSDL trung tâm" ready /><Connection label="Tệp minh chứng" value="Kho tệp riêng" ready /><Connection label="Bản cục bộ" value="IndexedDB + outbox" ready /><div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800">Google Drive/Gmail chỉ được bật bằng OAuth của đơn vị; phần mềm không lưu mật khẩu.</div></CardContent></Card></div></div>;
}

function SyncTile({ icon: Icon, label, value, tone }: { icon: React.ComponentType<{ className?: string }>; label: string; value: string; tone: string }) { return <Card className="rounded-2xl shadow-sm"><CardContent className="flex items-center gap-3 p-4"><span className={cn("rounded-xl p-2.5", tone === "green" && "bg-emerald-100 text-emerald-700", tone === "amber" && "bg-amber-100 text-amber-700", tone === "blue" && "bg-sky-100 text-sky-700")}><Icon className="size-5" /></span><div className="min-w-0"><p className="text-xs text-slate-500">{label}</p><p className="mt-0.5 truncate text-sm font-bold">{value}</p></div></CardContent></Card>; }
function Connection({ label, value, ready }: { label: string; value: string; ready: boolean }) { return <div className="flex items-center gap-3 rounded-xl border p-3"><span className={cn("size-2.5 rounded-full", ready ? "bg-emerald-500" : "bg-amber-500")} /><div className="flex-1"><p className="text-sm font-semibold">{label}</p><p className="text-xs text-slate-500">{value}</p></div><Badge className={ready ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}>{ready ? "Sẵn sàng" : "Chưa sẵn sàng"}</Badge></div>; }
